FILE cli.mjs
#!/usr/bin/env node
import { readFileSync } from 'node:fs';
import { parseRecords, summarizeRecords } from './records.mjs';

function serializeValidate(records) {
  return JSON.stringify(records);
}

const [command, file] = process.argv.slice(2);
if (command === 'help') process.stdout.write('record-report: validate <file> | summarize <file>\n');
else if (command === 'validate' || command === 'summarize') {
  try {
    const bytes = readFileSync(file);
    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes);
    const records = parseRecords(text);
    const result = command === 'validate'
      ? serializeValidate(records)
      : (() => {
          const { count, total } = summarizeRecords(records);
          return `{"count":${count},"total":${total.toString()}}`;
        })();
    process.stdout.write(result + '\n');
  } catch {
    process.stderr.write('INVALID_INPUT\n');
    process.exitCode = 2;
  }
} else { process.stderr.write('UNKNOWN_COMMAND\n'); process.exitCode = 2; }

FILE records.mjs
export function parseRecords(text) {
  if (text === '') return [];
  const rows = (text.endsWith('\n') ? text.slice(0, -1) : text).split('\n');
  const seen = new Set();
  return rows.map(row => {
    const match = /^([A-Za-z0-9_-]+),([0-9]+)$/.exec(row);
    if (!match || match[0] !== row) throw new Error('INVALID_INPUT');
    const [, id, digits] = match;
    const amount = Number(digits);
    if (!Number.isSafeInteger(amount) || seen.has(id)) throw new Error('INVALID_INPUT');
    seen.add(id);
    return { id, amount };
  });
}

export function summarizeRecords(records) {
  let total = 0n;
  for (const record of records) total += BigInt(record.amount);
  return { count: records.length, total };
}

